import{_t as e,it as t,n,ot as r,rt as i,xt as a}from"./chunks/framework.C5Z6qjff.js";var o=JSON.parse(`{"title":"Metamodel packages","description":"","frontmatter":{"title":"Metamodel packages","covers":{"screens":[],"stories":["US-033"]}},"headers":[],"relativePath":"administration/metamodel-packages.md","filePath":"administration/metamodel-packages.md"}`),s={name:`administration/metamodel-packages.md`};function c(n,o,s,c,l,u){let d=a(`Screenshot`);return e(),i(`div`,null,[o[0]||=t(`<h1 id="metamodel-packages" tabindex="-1">Metamodel packages <a class="header-anchor" href="#metamodel-packages" aria-label="Permalink to “Metamodel packages”">​</a></h1><p>A new instance has no entity types. Before anyone can capture entities, you import a metamodel: the shipped starter package or a package of your own.</p><p>Importing packages requires the permission <code>metamodel:write</code>, which only the role <code>metamodel-admin</code> holds – not the local system admin account. Map an IdP group to <code>metamodel-admin</code> (see <a href="./roles-and-permissions">Roles and permissions</a>); as a privileged role, it needs a second factor at the identity provider.</p><h2 id="import-the-starter-configuration" tabindex="-1">Import the starter configuration <a class="header-anchor" href="#import-the-starter-configuration" aria-label="Permalink to “Import the starter configuration”">​</a></h2><p>OEA ships the starter package <code>oea-starter-togaf-classic</code> with the entity types Application Component, Application Service, Data Object, Technology Component, Technology Service, System Software and Network Node, each with the property <em>Status</em>.</p><p>While the instance has no entity type, the start page shows <em>Import starter configuration</em> to a person with <code>metamodel:write</code>. Choose <em>Import</em> next to the package; the page confirms how many entity types are now available.</p>`,6),r(d,{name:`starter-import`,alt:`Start page with the starter configuration ready for import`}),o[1]||=t('<p>Through the API:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/metamodel/starter-packages&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                          # list with summary</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/metamodel/starter-packages/oea-starter-togaf-classic/import&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                       # imported entity types</span></span></code></pre></div><h2 id="import-your-own-package" tabindex="-1">Import your own package <a class="header-anchor" href="#import-your-own-package" aria-label="Permalink to “Import your own package”">​</a></h2><p>Packages of your own use the same JSON format (<code>MetamodelPackage</code>, with <code>packageId</code>, <code>packageVersion</code>, <code>publisher</code> and stable UUIDs per element). Import them with <code>POST /admin/metamodel/import</code>:</p><ul><li>A package is imported completely or not at all. Imported content gets the scope <code>imported</code> and the package as origin.</li><li>Importing the same package again updates its own content. Content of another package or of your organization is never overwritten; the answer is <code>409</code> with the list of conflicts.</li><li>Packages larger than <code>oea.metamodel.import.max-size</code> (default 10 MB) are rejected with <code>413</code>; faulty JSON or content that does not match the format with <code>422</code> and the location of the problem.</li><li>The strategy <code>replace</code>, viewpoints, shape assignments and translation bundles are not supported yet (<code>422</code>).</li></ul><p>Every import writes the audit events <code>metamodel.package-imported</code> and <code>metamodel.metatype-imported</code> with one batch ID.</p>',6)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};